// ===========================
// 10-1) 객체_스프레드시트컨트롤
// ===========================

function spreadsheetExamples() {
  // 현재 활성화된 스프레드시트 가져오기
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getActiveSheet();

  // ID로 스프레드시트 열기
  // var ss = SpreadsheetApp.openById('스프레드시트ID');

  // URL로 스프레드시트 열기
  // var ss = SpreadsheetApp.openByUrl('스프레드시트URL');

  // 새 스프레드시트 만들기
  // var newSS = SpreadsheetApp.create('새 스프레드시트');

  // 시트 관련 작업
  Logger.log("스프레드시트 이름: " + ss.getName());
  Logger.log("시트 이름: " + sheet.getName());
  Logger.log("시트 수: " + ss.getSheets().length);

  // 시트 추가/삭제/이름 변경
  var newSheet = ss.insertSheet("새 시트");
  newSheet.setName("이름 변경됨");
  // ss.deleteSheet(newSheet);  // 시트 삭제

  // 셀 데이터 읽기
  var value = sheet.getRange("A1").getValue();
  Logger.log("A1 값: " + value);

  // 셀 범위 데이터 읽기
  var values = sheet.getRange("A1:B3").getValues();
  Logger.log("A1:B3 값: " + JSON.stringify(values));

  // 셀 데이터 쓰기
  sheet.getRange("C1").setValue("테스트 데이터");

  // 여러 셀에 데이터 쓰기
  var dataToWrite = [
    ["이름", "나이", "직업"],
    ["김철수", 30, "교사"],
    ["이영희", 28, "개발자"]
  ];
  sheet.getRange(5, 1, 3, 3).setValues(dataToWrite);  // 5행 1열부터 3행 3열 크기

  // 서식 적용
  sheet.getRange("A1:C1").setFontWeight("bold");
  sheet.getRange("A1:C1").setBackground("#f3f3f3");

  // 셀 병합
  sheet.getRange("E1:G1").merge();
  sheet.getRange("E1").setValue("병합된 셀");

  // 행/열 삽입 및 삭제
  sheet.insertRowBefore(1);  // 첫 번째 행 앞에 삽입
  sheet.insertColumnAfter(1);  // 첫 번째 열 뒤에 삽입
  // sheet.deleteRow(1);  // 첫 번째 행 삭제
  // sheet.deleteColumn(1);  // 첫 번째 열 삭제

  // 특정 셀로 스크롤
  sheet.getRange("A1").activate();
}
